def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]
    op_c = op.count('C')
    op_d = n - op_c
    last_op = op[-1]
    last_me = me[-1]

    # Long-run cooperation streak
    coop_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            coop_streak += 1
        else:
            break

    # Opponent defection streak
    def_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            def_streak += 1
        else:
            break

    # Near the end: exploit known cooperators, defend against defectors
    remaining = 100 - n
    if remaining <= 3:
        if op_d == 0:
            return 'D'
        if op_d * 2 < n:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # Detect always-D early
    if n >= 6 and op_c == 0:
        return 'D'

    # Detect almost always-D
    if n >= 12 and op_d >= n - 1:
        return 'D'

    # Pure always-C opponent: keep cooperating most of the time to secure
    # the bulk payoff, only probing rarely until the very end.
    if op_d == 0:
        if n >= 30 and n % 11 == 0:
            return 'D'
        return 'C'

    # Very cooperative opponent: preserve mutual cooperation, probe sparingly
    if op_d * 10 <= n:
        if n >= 25 and def_streak == 0 and n % 13 == 0:
            return 'D'
        if last_op == 'D':
            # brief retaliation but return quickly
            if def_streak >= 2:
                return 'D'
            return 'D' if rng.random() < 0.7 else 'C'
        return 'C'

    # Mostly cooperative: cooperate, retaliate one step, then forgive
    if op_d * 2 < n:
        if last_op == 'C':
            return 'C'
        if def_streak >= 3:
            return 'D'
        # single or double defection: retaliate but reconcile soon
        if def_streak == 1:
            return 'D' if rng.random() < 0.75 else 'C'
        return 'D' if rng.random() < 0.6 else 'C'

    # Balanced or defection-heavy opponent
    if op_d * 3 >= n * 2:
        return 'D'

    # Around half defections: tit-for-tat with forgiveness and
    # occasional conciliatory moves to break retaliation chains
    if last_op == 'D':
        if last_me == 'D':
            # mutual defection: try conciliation occasionally
            if def_streak >= 4:
                return 'C' if rng.random() < 0.4 else 'D'
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        return 'D'
    else:
        # opponent cooperated
        if last_me == 'D':
            return 'C'
        if coop_streak >= 3 and n > 20 and rng.random() < 0.06:
            return 'D'
        return 'C'
